const [items, setItems] = useState([]);

// newest first; prepend arrivals as they come in
useEffect(() => subscribe((ev) => setItems((xs) => [toItem(ev), ...xs])), []);

const toItem = (ev) => ({
  id: ev.id,
  actor: { name: ev.user.name, avatar: ev.user.photoUrl },
  verb: "commented on",
  target: ev.doc.title,
  timestamp: ev.createdAt,
  icon: "message",
  unread: !ev.seen,
  body: ev.text,
});

<ActivityFeed
  title="Activity"
  items={items}
  height={480}
  loading={isLoading}
  error={loadError?.message}
  onRetry={refetch}
  onItemClick={(item) => openDoc(item.id)}
  onMarkRead={(ids) => markSeen(ids)}
  hasMore={hasMore}
  loadingMore={isFetchingMore}
  onLoadMore={fetchOlder}
/>
